insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-st-221","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A disproportionation reaction is one in which the same element is","options":["only oxidised","only reduced","simultaneously oxidised and reduced","left with an unchanged oxidation number"],"answer_index":2,"explanation":"Part of the element’s atoms rise in ON and part fall, as in $2\\mathrm{H_2O_2} \\rightarrow 2\\mathrm{H_2O} + \\mathrm{O_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing"},{"id":"che-st-222","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The combination $\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$ is classified as redox because","options":["no oxidation number changes","hydrogen is oxidised (0 to $+1$) and chlorine is reduced (0 to $-1$)","it is only an acid–base reaction","both elements are oxidised"],"answer_index":1,"explanation":"H$_2$ loses electrons and Cl$_2$ gains them, so the combination is a redox process.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing"},{"id":"che-st-223","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Which of the following laboratory changes is not a redox reaction?","options":["$2\\mathrm{H_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{H_2O}$","$\\mathrm{Zn} + \\mathrm{H_2SO_4} \\rightarrow \\mathrm{ZnSO_4} + \\mathrm{H_2}$","$\\mathrm{HCl} + \\mathrm{NaOH} \\rightarrow \\mathrm{NaCl} + \\mathrm{H_2O}$","$\\mathrm{Fe_2O_3} + 3\\mathrm{CO} \\rightarrow 2\\mathrm{Fe} + 3\\mathrm{CO_2}$"],"answer_index":2,"explanation":"Acid–base neutralisation exchanges H$^+$ and OH$^-$ with no change in oxidation numbers.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing"},{"id":"che-st-224","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In acid solution $\\mathrm{MnO_4^-}$ is reduced to $\\mathrm{Mn^{2+}}$. The number of electrons gained by one permanganate ion is","options":["2","3","5","7"],"answer_index":2,"explanation":"Mn goes from $+7$ to $+2$, a gain of five electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing"},{"id":"che-st-225","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Dichromate $\\mathrm{Cr_2O_7^{2-}}$ is reduced to two $\\mathrm{Cr^{3+}}$ ions in acid. Electrons consumed per dichromate ion are","options":["3","4","6","8"],"answer_index":2,"explanation":"Two chromium atoms each fall from $+6$ to $+3$, a total of six electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing"},{"id":"che-st-226","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The balanced acidic half-change $\\mathrm{MnO_4^-} + 8\\mathrm{H^+} + n\\,e^- \\rightarrow \\mathrm{Mn^{2+}} + 4\\mathrm{H_2O}$ requires $n$ equal to","options":["3","4","5","8"],"answer_index":2,"explanation":"Charge balance and the $+7 \\rightarrow +2$ change both fix $n = 5$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing"},{"id":"che-st-227","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Titration of $\\mathrm{Fe^{2+}}$ with acidic $\\mathrm{MnO_4^-}$ uses the mole ratio $\\mathrm{MnO_4^-} : \\mathrm{Fe^{2+}}$ equal to","options":["1 : 1","1 : 5","5 : 1","1 : 2"],"answer_index":1,"explanation":"One $\\mathrm{MnO_4^-}$ takes five electrons; each $\\mathrm{Fe^{2+}}$ supplies one, so five Fe$^{2+}$ are needed.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing"},{"id":"che-st-228","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In acid, dichromate oxidises $\\mathrm{H_2S}$ to sulphur: $\\mathrm{Cr_2O_7^{2-}} + 3\\mathrm{H_2S} + 8\\mathrm{H^+} \\rightarrow 2\\mathrm{Cr^{3+}} + 3\\mathrm{S} + 7\\mathrm{H_2O}$. The coefficient 3 in front of $\\mathrm{H_2S}$ appears because","options":["each H$_2$S loses 2 e$^-$ and dichromate gains 6 e$^-$","sulphur has atomic number 16","three oxygen atoms are present in dichromate","the reaction is not redox"],"answer_index":0,"explanation":"H$_2$S (S = $-2$ to 0) is a 2-electron reductant; Cr$_2$O$_7^{2-}$ is a 6-electron oxidant, so three H$_2$S balance one dichromate.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"redox-balancing"},{"id":"che-st-229","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Gram-equivalent mass of a substance is obtained from","options":["molar mass $\\times$ $n$-factor","molar mass / $n$-factor","molar mass + $n$-factor","molarity / $n$-factor"],"answer_index":1,"explanation":"Equivalent mass $= M / n$, where $n$ is the $n$-factor of the reaction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equivalents-normality"},{"id":"che-st-230","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrochloric acid donates one H$^+$ per formula unit, so its $n$-factor in acid–base work is","options":["1","2","3","0"],"answer_index":0,"explanation":"Monobasic HCl has $n = 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equivalents-normality"},{"id":"che-st-231","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Sulphuric acid is dibasic. In complete neutralisation its $n$-factor is","options":["1","2","3","4"],"answer_index":1,"explanation":"H$_2$SO$_4$ can furnish two H$^+$ ions, so $n = 2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equivalents-normality"},{"id":"che-st-232","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Normality $N$ and molarity $M$ of the same solution are related by","options":["$N = M / n$","$N = M \\times n$","$N = M + n$","$N = n / M$"],"answer_index":1,"explanation":"Each mole contributes $n$ equivalents, so $N = M \\times n$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equivalents-normality"},{"id":"che-st-233","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Sodium hydroxide has molar mass 40 g mol$^{-1}$ and $n = 1$. Its gram-equivalent mass is","options":["20 g eq$^{-1}$","40 g eq$^{-1}$","80 g eq$^{-1}$","23 g eq$^{-1}$"],"answer_index":1,"explanation":"For a monoacidic base, equivalent mass equals the molar mass, 40 g eq$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equivalents-normality"},{"id":"che-st-234","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Calcium hydroxide $\\mathrm{Ca(OH)_2}$ is a diacidic base, so its $n$-factor is","options":["1","2","3","4"],"answer_index":1,"explanation":"Two OH$^-$ ions per formula unit give $n = 2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equivalents-normality"},{"id":"che-st-235","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The number of gram-equivalents in a weighed sample equals","options":["mass $\\times$ equivalent mass","mass / equivalent mass","molar mass / mass","volume / normality"],"answer_index":1,"explanation":"Equivalents $= m / E$, just as moles $= m / M$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equivalents-normality"},{"id":"che-st-236","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Complete neutralisation of sulphuric acid uses $n = 2$. The equivalent mass of $\\mathrm{H_2SO_4}$ (M = 98) is therefore","options":["24.5 g eq$^{-1}$","49 g eq$^{-1}$","98 g eq$^{-1}$","196 g eq$^{-1}$"],"answer_index":1,"explanation":"$E = 98/2 = 49$ g eq$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality"},{"id":"che-st-237","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A bottle labelled 0.50 M $\\mathrm{H_2SO_4}$ is used as a dibasic acid. The normality of that solution is","options":["0.25 N","0.50 N","1.0 N","2.0 N"],"answer_index":2,"explanation":"$N = M \\times n = 0.50 \\times 2 = 1.0$ N.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality"},{"id":"che-st-238","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In acidic medium $\\mathrm{KMnO_4}$ is reduced to $\\mathrm{Mn^{2+}}$. The $n$-factor of permanganate in that change is","options":["1","3","5","7"],"answer_index":2,"explanation":"Mn falls from $+7$ to $+2$, a five-electron change, so $n = 5$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality"},{"id":"che-st-239","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Potassium permanganate (M = 158 g mol$^{-1}$) used in acidic titration has equivalent mass","options":["31.6 g eq$^{-1}$","52.7 g eq$^{-1}$","79.0 g eq$^{-1}$","158 g eq$^{-1}$"],"answer_index":0,"explanation":"$E = 158/5 = 31.6$ g eq$^{-1}$ for the five-electron acidic reduction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equivalents-normality"},{"id":"che-st-240","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Twenty-five millilitres of 0.20 N $\\mathrm{H_2SO_4}$ are titrated with 0.10 N NaOH. The volume of alkali required for complete neutralisation is","options":["12.5 mL","25 mL","50 mL","100 mL"],"answer_index":2,"explanation":"$N_1V_1 = N_2V_2$ gives $V(\\mathrm{NaOH}) = (0.20 \\times 25)/0.10 = 50$ mL.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"equivalents-normality"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-st-221","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-222","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-223","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-224","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-225","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-226","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-227","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-228","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-229","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-230","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-231","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-232","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-233","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-234","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-235","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-236","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-237","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-238","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-239","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-st-240","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
